import type { ComponentMetadata, PropertyMetadata } from '@uds/metadata';

export const generatedBanner =
  '// Generated by @uds/generators from component metadata. Do not edit.';

export function className(id: string): string {
  const pascal = id
    .split('-')
    .map((part) => {
      const head = part.charAt(0).toUpperCase();
      return `${head}${part.slice(1)}`;
    })
    .join('');
  return `Uds${pascal}`;
}

/** `uds-change` → `onUdsChange` (ADR-0006). */
export function reactEventName(eventName: string): string {
  const pascal = eventName
    .split('-')
    .map((part) => `${part.charAt(0).toUpperCase()}${part.slice(1)}`)
    .join('');
  return `on${pascal}`;
}

/** `uds-change` → `udsChange`. */
export function angularOutputName(eventName: string): string {
  const [first, ...rest] = eventName.split('-');
  if (first === undefined) return eventName;
  const tail = rest.map((part) => `${part.charAt(0).toUpperCase()}${part.slice(1)}`).join('');
  return `${first}${tail}`;
}

export function isFormValue(metadata: ComponentMetadata): boolean {
  return (
    metadata.category === 'forms' &&
    metadata.properties.some((property) => property.name === 'value')
  );
}

function quote(value: string): string {
  return `'${value.replaceAll('\\', '\\\\').replaceAll("'", "\\'")}'`;
}

export function propertyTsType(property: PropertyMetadata): string {
  const type = property.type;
  switch (type.kind) {
    case 'string':
    case 'icon':
      return 'string';
    case 'number':
      return 'number';
    case 'boolean':
      return 'boolean';
    case 'enum':
      return type.values.map((value) => quote(value)).join(' | ');
    case 'object':
      return 'unknown';
    default: {
      const unreachable: never = type;
      return unreachable;
    }
  }
}

export function propertyDefault(property: PropertyMetadata): string {
  const value = property.default;
  if (typeof value === 'string') return quote(value);
  if (typeof value === 'boolean' || typeof value === 'number') return String(value);
  switch (property.type.kind) {
    case 'boolean':
      return 'false';
    case 'number':
      return '0';
    case 'string':
    case 'icon':
      return "''";
    case 'enum': {
      const first = property.type.values[0];
      if (first === undefined) throw new Error(`Enum ${property.name} has no values`);
      return quote(first);
    }
    case 'object':
      return 'undefined';
    default: {
      const unreachable: never = property.type;
      return unreachable;
    }
  }
}
